struct anim_control_t {};
struct vector3d { float x, y, z; vector3d operator+(const vector3d&) const; };
struct quaternion { float x, y, z, w; quaternion operator*(const quaternion&) const; };
struct vector4d { float x, y, z, w; } __attribute__((aligned(16)));
struct matrix4x4 { vector4d x, y, z, w; };
class po { matrix4x4 m; public: po(const vector3d&, const quaternion&, float); };
template<class T> class anim {
protected: unsigned short flags;
public:
  virtual void set_flag(int); virtual void clear_flag(int);
  virtual void set_flag(int, bool); virtual void set_time(float);
  virtual void frame_advance(const anim_control_t&, T*);
  virtual void get_value(const anim_control_t&, T*) const;
  virtual void get_value(float, T*) const;
  bool is_valid() const { return flags & 0x1000; }
};
inline vector3d anim_xform3d_1(const vector3d *rot, const vector3d &sv)
{
  vector3d res;
  res.x = rot[0].x * sv.x + rot[1].x * sv.y + rot[2].x * sv.z;
  res.y = rot[0].y * sv.x + rot[1].y * sv.y + rot[2].y * sv.z;
  res.z = rot[0].z * sv.x + rot[1].z * sv.y + rot[2].z * sv.z;
  return(res);
}
class po_anim: public anim<po> {
  anim<vector3d>* P; anim<quaternion>* R; anim<float>* S;
  vector3d P_start; quaternion R_start; float S_start;
  vector3d R_start_mat[3];
public:
  bool has_P() const { return P && P->is_valid(); }
  bool has_R() const { return R && R->is_valid(); }
  bool has_S() const { return S && S->is_valid(); }
  bool is_relative_to_start() const { return flags & 0x20; }
  void get_value(const anim_control_t&, po*) const;
};
void po_anim::get_value( const anim_control_t& ac, po* dest ) const
{
  vector3d p;
  if ( has_P() )
  {
    P->get_value( ac, &p );
    if ( is_relative_to_start() )
      p = anim_xform3d_1(&R_start_mat[0], p) + P_start;
  }
  else
    p = P_start;
  quaternion r;
  if ( has_R() )
  {
    R->get_value( ac, &r );
    if ( is_relative_to_start() )
      r = r * R_start;
  }
  else
    r = R_start;
  float s;
  if ( has_S() )
  {
    S->get_value( ac, &s );
    if ( is_relative_to_start() )
      s *= S_start;
  }
  else
    s = S_start;
  *dest = po( p, r, s );
}
